    sep = None
    for r in range(nrows):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            sep = grid[r][0]
            break
    if sep is None:                # fallback: most frequent non‑zero value
        from collections import Counter
        cnt = Counter(v for row in grid for v in row if v != 0)
        sep = cnt.most_common(1)[0][0]

    # ----- identify colours (values different from 0 and separator) -----
    colours = {v for row in grid for v in row if v != 0 and v != sep}

    # ----- content rows (rows that are not the separator row) -----
    content_rows = [i for i in range(nrows) if not all(cell == sep for cell in grid[i])]
    # map a content row to its block‑row index (each block row consists of two consecutive content rows)
    block_of_row = {}
    for idx, r in enumerate(content_rows):
        block_of_row[r] = idx // 2

    # copy original grid – we will write the result into out
    out = [row[:] for row in grid]

    # ------------------- horizontal fills -------------------
    for c in colours:
        for r in range(nrows):
            cols = [ccol for ccol in range(ncols) if grid[r][ccol] == c]
