            mn, mx = min(cols), max(cols)
            for ccol in range(mn, mx + 1):
                if grid[r][ccol] == 0:
                    out[r][ccol] = c

    # ------------------- vertical fills --------------------
    for c in colours:
        for ccol in range(ncols):
            rows = [r for r in range(nrows) if grid[r][ccol] == c]
            if len(rows) < 2:
                continue
            # column may contain other non‑separator values ?
            col_vals = {v for r in range(nrows) if (v := grid[r][ccol]) != 0 and v != sep}
            if col_vals != {c}:
                continue

            first_row = rows[0]
            br_first = block_of_row[first_row]
            br_fill = br_first + 1

            # the two rows that form the block row br_fill
            if br_fill * 2 + 1 < len(content_rows):
                r1 = content_rows[br_fill * 2]
                r2 = content_rows[br_fill * 2 + 1]
                if grid[r1][ccol] == 0:
                    out[r1][ccol] = c
                if grid[r2][ccol] == 0:
                    out[r2][ccol] = c

